"""Host behavioral tests for the actual runtime.c FILE cache using a mock NAND API."""
from pathlib import Path
import argparse
import os
import shutil
import subprocess
import tempfile

PREFIX = '\n#include <stdint.h>\n#include <stddef.h>\n#include <stdlib.h>\n#include <stdio.h>\n#include <string.h>\n#include <assert.h>\n#include <ctype.h>\ntypedef struct {int handle,error;unsigned char*cache;size_t cache_size,position;int eof,cache_borrowed;} TestFile;\nstatic unsigned char contents[4096]="0123456789";\nstatic int position,bytes=10,reads,closes,writes,partial_once,allocation_fail,opens,pack_frees;\nstatic void *watched_pack;\nstatic void reset_mock(void){position=reads=closes=writes=partial_once=allocation_fail=opens=pack_frees=0;watched_pack=0;bytes=10;}\nstatic void test_free(void*p){if(p&&p==watched_pack)++pack_frees;free(p);}\nstatic void log_append(const char*s,size_t n){(void)s;(void)n;}\nstatic void*test_malloc(size_t n){if(allocation_fail){allocation_fail=0;return 0;}return malloc(n);}\nstatic int bda_fs_fopen_raw(const char*p,const char*m){assert(!strchr(p,\'/\'));(void)m;position=0;++opens;return 1;}\nstatic int bda_fs_file_is_valid(int h){return h==1;}\nstatic int bda_fs_close_raw(int h){assert(h==1);++closes;return 0;}\nstatic int bda_fs_seek_raw(int h,long o,int w){assert(h==1);long p=w==0?o:w==1?position+o:bytes+o;if(p<0)return -1;return position=(int)p;}\nstatic int bda_fs_tell_raw(int h){assert(h==1);return position;}\nstatic int bda_fs_fread_raw(void*p,size_t size,size_t n,int h){assert(h==1);++reads;size_t available=position<bytes?(size_t)(bytes-position):0,total=size*n;if(total>available)total=available;if(partial_once&&total){--total;partial_once=0;}assert(total<=sizeof(contents));memcpy(p,contents+position,total);position+=(int)total;return (int)(total/size);}\nstatic int bda_fs_read_raw(int h,void*p,size_t n){return bda_fs_fread_raw(p,1,n,h);}\nstatic int bda_fs_fwrite_raw(const void*p,size_t s,size_t n,int h){assert(h==1);(void)p;(void)s;++writes;return (int)n;}\nstatic void bda_fs_flush_all(void){}\n#define FILE TestFile\n#undef stdout\n#define stdout test_stdout\n#undef stderr\n#define stderr test_stderr\n#define malloc test_malloc\n#define free test_free\n#define fopen mem_fopen\n#define fclose mem_fclose\n#define fread mem_fread\n#define fwrite mem_fwrite\n#define fgetc mem_fgetc\n#define fseek mem_fseek\n#define ftell mem_ftell\n#define ferror mem_ferror\n#define feof mem_feof\n#define fflush mem_fflush\n'

TESTS = '\nstatic void put32(unsigned at,unsigned value){for(unsigned i=0;i<4;++i)contents[at+i]=(unsigned char)(value>>(i*8));}\nstatic void make_pack(void){\n reset_mock();memset(contents,0,sizeof(contents));memcpy(contents,"SCPAK01\\0",8);put32(8,2);\n strcpy((char*)contents+16,"PINBALL.DAT");put32(48,96);put32(52,10);\n strcpy((char*)contents+56,"SOUND.WAV");put32(88,108);put32(92,4);\n memcpy(contents+96,"0123456789",10);memcpy(contents+108,"WAVE",4);bytes=112;\n}\nint main(void){\n char buffer[16]={0};reset_mock();FILE*f=fopen("A:/Pinball/PINBALL.DAT","rb");\n assert(f&&f->cache&&reads==1&&closes==1&&ftell(f)==0&&!feof(f));\n assert(fread(buffer,4,3,f)==2&&ftell(f)==10&&feof(f)&&!memcmp(buffer,"0123456789",10));\n assert(fseek(f,-2,SEEK_END)==0&&!feof(f)&&ftell(f)==8);assert(fgetc(f)==\'8\'&&fgetc(f)==\'9\'&&fgetc(f)==EOF&&feof(f));\n assert(fseek(f,-1,SEEK_SET)==-1&&ftell(f)==10);assert(fwrite(buffer,1,1,f)==0&&ferror(f));assert(fclose(f)==0&&closes==1);\n reset_mock();f=fopen("file","wb");assert(f&&!f->cache&&reads==0);assert(fwrite(buffer,2,3,f)==3&&writes==1);assert(fclose(f)==0&&closes==1);\n reset_mock();f=fopen("file","r+");assert(f&&!f->cache&&reads==0);assert(fread(buffer,1,12,f)==10&&feof(f));assert(fseek(f,0,SEEK_SET)==0&&!feof(f));assert(fclose(f)==0&&closes==1);\n reset_mock();partial_once=1;f=fopen("file","rb");assert(f&&!f->cache&&reads==1&&closes==0&&ftell(f)==0);assert(fread(buffer,1,5,f)==5&&!memcmp(buffer,"01234",5));assert(fclose(f)==0&&closes==1);\n reset_mock();allocation_fail=1;f=fopen("file","rb");assert(f&&!f->cache&&reads==0&&ftell(f)==0);assert(fread(buffer,1,2,f)==2);assert(fclose(f)==0);\n reset_mock();bytes=4*1024*1024+1;f=fopen("file","rb");assert(f&&!f->cache&&reads==0&&ftell(f)==0);assert(fclose(f)==0);\n reset_mock();bytes=0;f=fopen("file","rb");assert(f&&f->cache&&closes==1&&reads==0&&ftell(f)==0);assert(fgetc(f)==EOF&&feof(f));assert(fseek(f,100,SEEK_SET)==0&&ftell(f)==100&&fgetc(f)==EOF);assert(fclose(f)==0);\n\n make_pack();assert(scp_resource_mount("A:/Pinball/RESOURCES.PAK")==1&&reads==1&&opens==1&&closes==1);watched_pack=resource_pack;\n assert(scp_resource_mount("ignored")==0&&opens==1);\n FILE*a=fopen("B:/Other/pinball.dat","rb"),*b=fopen("A:\\\\different\\\\sound.wav","r");\n assert(a&&b&&a->cache_borrowed&&b->cache_borrowed&&opens==1&&reads==1&&closes==1);\n assert(fread(buffer,4,3,a)==2&&ftell(a)==10&&feof(a));assert(fseek(a,-2,SEEK_END)==0&&fgetc(a)==\'8\'&&!feof(a));\n assert(fread(buffer,1,4,b)==4&&!memcmp(buffer,"WAVE",4));assert(fclose(a)==0&&fclose(b)==0&&pack_frees==0&&closes==1);\n a=fopen("SCORE0.SAV","wb");assert(a&&!a->cache&&opens==2);assert(fwrite(buffer,1,4,a)==4);fclose(a);\n a=fopen("PINBALL.DAT","r+");assert(a&&!a->cache&&opens==3);fclose(a);\n a=fopen("PINBALL.DAT","rb");assert(a&&a->cache_borrowed&&fgetc(a)==\'0\');fclose(a);\n scp_resource_unmount();assert(pack_frees==1&&!resource_pack);scp_resource_unmount();assert(pack_frees==1);\n make_pack();contents[0]=\'X\';assert(!scp_resource_mount("bad"));\n make_pack();put32(8,129);assert(!scp_resource_mount("bad"));\n make_pack();put32(48,108);put32(52,10);assert(!scp_resource_mount("bad"));\n make_pack();memset(contents+16,\'A\',32);assert(!scp_resource_mount("bad"));\n make_pack();strcpy((char*)contents+56,"pinball.dat");assert(!scp_resource_mount("bad"));\n make_pack();put32(48,20);assert(!scp_resource_mount("bad"));\n make_pack();partial_once=1;assert(!scp_resource_mount("short"));\n printf("resource archive: single raw read, case-insensitive basename views, borrowed close ownership, seek/EOF, save/r+ bypass, idempotent unmount and malformed archive rejection passed\\n");\n printf("memory FILE: batched load, item/partial-element semantics, seek/tell/EOF, write protection, r+ bypass, short-read/allocation fallback, large/empty files passed\\n");\n return 0;\n}\n'

def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--cc', default=os.environ.get('CC') or shutil.which('gcc') or 'gcc')
    args = parser.parse_args()
    runtime = Path(__file__).with_name('runtime.c').read_text(encoding='utf-8')
    actual = runtime[runtime.index('static FILE console='):runtime.index('typedef struct{char*p;size_t capacity,used;} Formatter;')]
    env = os.environ.copy()
    env['PATH'] = str(Path(args.cc).resolve().parent) + os.pathsep + env.get('PATH', '')
    with tempfile.TemporaryDirectory(prefix='scp-file-test-') as temp:
        source = Path(temp) / 'file-cache-test.c'
        binary = Path(temp) / 'file-cache-test.exe'
        source.write_text(PREFIX + actual + TESTS, encoding='utf-8')
        subprocess.run([args.cc, '-std=c11', '-O2', '-Wall', '-Wextra', '-Werror', '-Wno-misleading-indentation', '-fno-builtin', str(source), '-o', str(binary)], env=env, check=True)
        subprocess.run([str(binary)], env=env, check=True)

if __name__ == '__main__':
    main()
